`timescale 1ns / 1ps

// Board wrapper for Nexys A7-100T (xc7a100tcsg324-1).
// Automatic sequence: logo -> alignment target -> low-poly space painting -> orbiting satellite.
// BTNU skips the current completed-picture hold. CPU_RESETN restarts the
// sequence; full-screen clears use the MGPU clear engine.
module top #(
    parameter BUTTON_FILTER_BITS = 16,
    // Default /16 = 6.25 MHz, leaves time for the original combinational
    // dividers. If changed for hardware, update the XDC generated clock too.
    parameter GPU_CLK_DIV_LOG2 = 4,
    parameter LOGO_HOLD_MS = 4000,
    parameter STAGE_HOLD_MS = 4000,
    parameter CUBE_HOLD_MS = 40,
    // Legacy parameter retained for compatibility; new art uses fixed coordinates.
    parameter CUBE_HALF_SIZE = 96
)(
    input  wire       CLK100MHZ,
    input  wire       CPU_RESETN,
    input  wire       BTNU,
    output wire [3:0] VGA_R,
    output wire [3:0] VGA_G,
    output wire [3:0] VGA_B,
    output wire       VGA_HS,
    output wire       VGA_VS
);
    // Configuration initialization also guarantees a reset without a button.
    // Both assertion and release are synchronized: an asynchronous reset
    // must not directly change a block RAM's read/write enable pins.
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [3:0] reset_pipe = 4'b1111;
    always @(posedge CLK100MHZ) begin
        reset_pipe <= {reset_pipe[2:0], !CPU_RESETN};
    end
    wire vga_rst = reset_pipe[3];

    // Free-running divider, routed through a dedicated global clock buffer.
    // Never gate or restart this clock with a button.
    reg [GPU_CLK_DIV_LOG2-1:0] gpu_divider = 0;
    always @(posedge CLK100MHZ)
        gpu_divider <= gpu_divider + 1'b1;
    wire gpu_clk;
`ifdef __ICARUS__
    // Icarus does not provide Xilinx primitives; BUFG is logically a wire.
    assign gpu_clk = gpu_divider[GPU_CLK_DIV_LOG2-1];
`else
    BUFG u_gpu_clk_buf (.I(gpu_divider[GPU_CLK_DIV_LOG2-1]), .O(gpu_clk));
`endif

    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [3:0] gpu_reset_pipe = 4'b1111;
    always @(posedge gpu_clk) begin
        gpu_reset_pipe <= {gpu_reset_pipe[2:0], !CPU_RESETN};
    end
    wire rst = gpu_reset_pipe[3];

    (* ASYNC_REG = "TRUE" *) reg [1:0] button_sync;
    reg [BUTTON_FILTER_BITS-1:0] button_count;
    reg button_level;
    reg button_press;
    always @(posedge gpu_clk) begin
        if (rst) begin
            button_sync  <= 2'b00;
            button_count <= 0;
            button_level <= 1'b0;
            button_press <= 1'b0;
        end else begin
            button_sync <= {button_sync[0], BTNU};
            button_press <= 1'b0;
            if (button_sync[1] == button_level) begin
                button_count <= 0;
            end else if (&button_count) begin
                button_level <= button_sync[1];
                button_press <= button_sync[1];
                button_count <= 0;
            end else begin
                button_count <= button_count + 1'b1;
            end
        end
    end

    // The generated ROM contains triangle commands, never framebuffer pixels.
    // The GPU still rasterizes and shades every triangle through its normal input.
    localparam GPU_HZ=100000000/(1 << GPU_CLK_DIV_LOG2);
    localparam STAGE_TICKS=(GPU_HZ/1000)*STAGE_HOLD_MS;
    localparam FRAME_TICKS=(GPU_HZ/1000)*CUBE_HOLD_MS;
    localparam FETCH=0, LOAD=1, ISSUE=2, WAIT_GPU=3, ADVANCE=4, HOLD=5, CLEAR_ISSUE=6, CLEAR_WAIT=7;
    localparam LOGO_LAST=14'd12799;
    localparam LOGO_TICKS=(GPU_HZ/1000)*LOGO_HOLD_MS;
    reg logo_active;
    reg [13:0] logo_command;
    wire [13:0] logo_offset=logo_command-14'd2;
    wire [12:0] logo_address=(logo_command<2) ? 13'd0 : logo_offset[13:1];
    wire [35:0] logo_data;
    boot_logo_rom u_logo_rom(gpu_clk,logo_address,logo_data);
    wire [9:0] logo_left=10'd32+logo_data[27:18];
    wire [9:0] logo_right=logo_left+((logo_data[17:8]>1) ? logo_data[17:8]-10'd1 : 10'd1);
    wire [9:0] logo_y=10'd120+{2'b0,logo_data[35:28]};
    reg [2:0] demo_state;
    reg [1:0] scene;
    reg [4:0] animation_frame;
    reg [31:0] hold_count;
    reg [12:0] command_address;
    reg [12:0] drain_count;
    reg saw_busy;
    reg demo_start;
    reg demo_clear;
    wire gpu_busy,gpu_done;
    reg [9:0] gpu_x0,gpu_y0,gpu_x1,gpu_y1,gpu_x2,gpu_y2;
    reg [7:0] gpu_c0,gpu_c1,gpu_c2;
    wire [83:0] command_data;
    wire [83:0] board_command_data;
    space_triangle_rom u_scene_rom(gpu_clk,command_address,board_command_data);
    // STUDIO_SIMULATION command source: defined only by the Studio testbench.
    // Normal synthesis and board simulation keep the original ROM/controller.
`ifdef STUDIO_SIMULATION
    wire studio_mode;
    wire [17:0] studio_count;
    reg [17:0] studio_index;
    reg studio_finished;
    wire [83:0] studio_data;
    studio_triangle_source u_studio_source(gpu_clk,studio_index,studio_data,studio_mode,studio_count);
    assign command_data=studio_mode ? studio_data : board_command_data;
`else
    assign command_data=board_command_data;
`endif
    localparam ART_START=13'd24, ART_END=13'd4930;
    function [12:0] frame_start;
        input [4:0] index;
        begin
            case(index)
                5'd0: frame_start=13'd4931;
                5'd1: frame_start=13'd4970;
                5'd2: frame_start=13'd5009;
                5'd3: frame_start=13'd5048;
                5'd4: frame_start=13'd5087;
                5'd5: frame_start=13'd5126;
                5'd6: frame_start=13'd5165;
                5'd7: frame_start=13'd5204;
                5'd8: frame_start=13'd5243;
                5'd9: frame_start=13'd5282;
                5'd10: frame_start=13'd5321;
                5'd11: frame_start=13'd5360;
                5'd12: frame_start=13'd5399;
                5'd13: frame_start=13'd5438;
                5'd14: frame_start=13'd5477;
                5'd15: frame_start=13'd5516;
                5'd16: frame_start=13'd5555;
                5'd17: frame_start=13'd5594;
                5'd18: frame_start=13'd5633;
                5'd19: frame_start=13'd5672;
                5'd20: frame_start=13'd5711;
                5'd21: frame_start=13'd5750;
                5'd22: frame_start=13'd5789;
                5'd23: frame_start=13'd5828;
                5'd24: frame_start=13'd5867;
                5'd25: frame_start=13'd5906;
                5'd26: frame_start=13'd5945;
                5'd27: frame_start=13'd5984;
                5'd28: frame_start=13'd6023;
                5'd29: frame_start=13'd6062;
                5'd30: frame_start=13'd6101;
                5'd31: frame_start=13'd6140;
                default: frame_start=13'd4931;
            endcase
        end
    endfunction
    function [12:0] frame_end;
        input [4:0] index;
        begin
            case(index)
                5'd0: frame_end=13'd4969;
                5'd1: frame_end=13'd5008;
                5'd2: frame_end=13'd5047;
                5'd3: frame_end=13'd5086;
                5'd4: frame_end=13'd5125;
                5'd5: frame_end=13'd5164;
                5'd6: frame_end=13'd5203;
                5'd7: frame_end=13'd5242;
                5'd8: frame_end=13'd5281;
                5'd9: frame_end=13'd5320;
                5'd10: frame_end=13'd5359;
                5'd11: frame_end=13'd5398;
                5'd12: frame_end=13'd5437;
                5'd13: frame_end=13'd5476;
                5'd14: frame_end=13'd5515;
                5'd15: frame_end=13'd5554;
                5'd16: frame_end=13'd5593;
                5'd17: frame_end=13'd5632;
                5'd18: frame_end=13'd5671;
                5'd19: frame_end=13'd5710;
                5'd20: frame_end=13'd5749;
                5'd21: frame_end=13'd5788;
                5'd22: frame_end=13'd5827;
                5'd23: frame_end=13'd5866;
                5'd24: frame_end=13'd5905;
                5'd25: frame_end=13'd5944;
                5'd26: frame_end=13'd5983;
                5'd27: frame_end=13'd6022;
                5'd28: frame_end=13'd6061;
                5'd29: frame_end=13'd6100;
                5'd30: frame_end=13'd6139;
                5'd31: frame_end=13'd6178;
                default: frame_end=13'd4969;
            endcase
        end
    endfunction
    wire last_command=
`ifdef STUDIO_SIMULATION
        studio_mode ? (studio_index+18'd1>=studio_count) :
`endif
        logo_active ? (logo_command==LOGO_LAST) : (scene==0 && command_address==23) ||
                      (scene==1 && command_address==ART_END) ||
                      (scene==2 && command_address==frame_end(animation_frame));
    // Hardware full-screen clear handshake. Scene ROM addresses stay stable;
    // skip the two old full-screen triangles after the clear has completed.
    wire needs_full_clear =
`ifdef STUDIO_SIMULATION
        !studio_mode &&
`endif
        (logo_active ? (logo_command==0) :
         ((scene==0 && command_address==0) ||
          (scene==1 && command_address==ART_START)));
    always @(posedge gpu_clk) begin
        if(rst) begin
            demo_state<=FETCH; scene<=0; animation_frame<=0;
            logo_active<=1;logo_command<=0;
`ifdef STUDIO_SIMULATION
            studio_index<=0;studio_finished<=0;
            if(studio_mode) begin logo_active<=0;scene<=1;end
`endif
            command_address<=0; hold_count<=0; drain_count<=0;
            saw_busy<=0; demo_start<=0; demo_clear<=0;
            gpu_x0<=0;gpu_y0<=0;gpu_x1<=0;gpu_y1<=0;gpu_x2<=0;gpu_y2<=0;
            gpu_c0<=0;gpu_c1<=0;gpu_c2<=0;
        end else begin
            demo_start<=0; demo_clear<=0;
            case(demo_state)
                FETCH: begin
                    demo_state<=needs_full_clear ? CLEAR_ISSUE : LOAD; // synchronous source read
`ifdef STUDIO_SIMULATION
                    if(studio_mode && studio_count==0) begin
                        studio_finished<=1;demo_state<=HOLD;
                    end
`endif
                end
                CLEAR_ISSUE: begin
                    // Entered only at startup or after a completed scene hold.
                    demo_clear<=1; saw_busy<=0;
                    demo_state<=CLEAR_WAIT;
                end
                CLEAR_WAIT: begin
                    if(gpu_busy) saw_busy<=1;
                    if(saw_busy && !gpu_busy) begin
                        if(logo_active) logo_command<=14'd2;
                        else command_address<=command_address+13'd2;
                        demo_state<=FETCH;
                    end
                end
                LOAD: begin
                    if(logo_active) begin
                        if(logo_command<2) begin
                            gpu_x0<=0;gpu_y0<=0;gpu_x1<=639;
                            gpu_y1<=logo_command[0] ? 479 : 0;
                            gpu_x2<=logo_command[0] ? 0 : 639;gpu_y2<=479;
                            gpu_c0<=0;gpu_c1<=0;gpu_c2<=0;
                        end else begin
                            gpu_x0<=logo_left;gpu_y0<=logo_y;
                            gpu_x1<=logo_right;gpu_y1<=logo_command[0] ? logo_y+10'd1 : logo_y;
                            gpu_x2<=logo_command[0] ? logo_left : logo_right;gpu_y2<=logo_y+10'd1;
                            gpu_c0<=logo_data[7:0];gpu_c1<=logo_data[7:0];gpu_c2<=logo_data[7:0];
                        end
                    end else begin
                        {gpu_x0,gpu_y0,gpu_x1,gpu_y1,gpu_x2,gpu_y2,
                         gpu_c0,gpu_c1,gpu_c2}<=command_data;
                    end
                    demo_state<=ISSUE;
                end
                ISSUE: begin
                    demo_start<=1; saw_busy<=0; drain_count<=0;
                    demo_state<=WAIT_GPU;
                end
                WAIT_GPU: begin
                    if(gpu_busy) begin saw_busy<=1;drain_count<=0;end
                    else if(saw_busy) drain_count<=drain_count+1'b1;
                    // User's gpu_done can miss tiny triangles whose last pixel
                    // retires before rasterization ends. Only in that case use
                    // the original bounded drain: 8192 > 256*18 + one in flight.
                    if(saw_busy && (gpu_done || (!gpu_busy && &drain_count)))
                        demo_state<=ADVANCE;
                end
                ADVANCE: begin
                    if(last_command) begin
`ifdef STUDIO_SIMULATION
                        if(studio_mode) studio_finished<=1;
`endif
                        hold_count<=logo_active ? ((LOGO_TICKS>0)?LOGO_TICKS-1:0) : scene==2 ? ((FRAME_TICKS>0)?FRAME_TICKS-1:0)
                                                   : ((STAGE_TICKS>0)?STAGE_TICKS-1:0);
                        demo_state<=HOLD;
                    end else begin
`ifdef STUDIO_SIMULATION
                        if(studio_mode) studio_index<=studio_index+1'b1;
                        else
`endif
                        if(logo_active) logo_command<=logo_command+1'b1;
                        else command_address<=command_address+1'b1;
                        demo_state<=FETCH;
                    end
                end
                HOLD: begin
`ifdef STUDIO_SIMULATION
                    if(studio_mode) begin demo_state<=HOLD;end
                    else
`endif
                    if(hold_count==0 || button_press) begin
                        if(logo_active) begin
                            logo_active<=0;command_address<=0;
                        end else if(scene==0) begin scene<=1;command_address<=ART_START;end
                        else if(scene==1) begin
                            scene<=2;animation_frame<=0;command_address<=frame_start(0);
                        end else begin
                            animation_frame<=animation_frame+1'b1;
                            command_address<=frame_start(animation_frame+5'd1);
                        end
                        demo_state<=FETCH;
                    end else hold_count<=hold_count-1'b1;
                end
                default: demo_state<=FETCH;
            endcase
        end
    end
    mgpu u_mgpu (
        .clk(gpu_clk), .rst(rst), .start(demo_start), .clear(demo_clear),
        .x0(gpu_x0), .y0(gpu_y0), .x1(gpu_x1), .y1(gpu_y1), .x2(gpu_x2), .y2(gpu_y2),
        .clor0(gpu_c0), .clor1(gpu_c1), .clor2(gpu_c2),
        .clear_color(8'h00), .gpu_busy(gpu_busy), .gpu_done(gpu_done),
        .vga_clk(CLK100MHZ), .vga_rst(vga_rst),
        .vga_r(VGA_R), .vga_g(VGA_G), .vga_b(VGA_B), .vga_hs(VGA_HS), .vga_vs(VGA_VS)
    );
endmodule

